# Set up sound system and start music
try:
    # Restart the Pygame audio mixer which Pygame Zero sets up by default. We find that the default settings
    # cause issues with delayed or non-playing sounds on some devices
    mixer.quit()
    mixer.init(44100, -16, 2, 1024)

    music.play("theme")
    music.set_volume(0.3)
except Exception:
    # If an error occurs (e.g. no sound hardware), ignore it
    pass

total_frames: int = 0

# Set up controls
keyboard_controls: KeyboardControls = KeyboardControls()
setup_joystick_controls()

# Set the initial game state
state = State.TITLE
# game is None ONLY while on the title screen, and nothing touches it there;
# all actor/game code runs under the invariant that a real Game exists.  The
# cast documents that invariant for the type checker (same idiom as cavern's
# Game.player) instead of leaving ~74 unguarded Optional accesses.
game: "Game" = cast("Game", None)

# Tell Pygame Zero to take over
# --- beatstreets owns its game loop ------------------------------------------
# Was pgzero_gl.runner.main(): a framework that owned the loop and called back
# into this module's update()/draw(). Now beatstreets runs the loop itself and
# calls *down* into the renderer -- the course's library-not-framework style.
if __name__ == "__main__":
    Context.asset_root = os.path.dirname(os.path.abspath(__file__))

    if not glfw.init():
        raise RuntimeError("glfw.init() failed")
    Context.glfw_ready = True
    glfw.window_hint(glfw.CONTEXT_VERSION_MAJOR, 3)
    glfw.window_hint(glfw.CONTEXT_VERSION_MINOR, 3)
    glfw.window_hint(glfw.OPENGL_PROFILE, glfw.OPENGL_CORE_PROFILE)
    glfw.window_hint(glfw.OPENGL_FORWARD_COMPAT, glfw.TRUE)
    window = glfw.create_window(WIDTH, HEIGHT, TITLE, None, None)
    if not window:
        glfw.terminate()
        raise RuntimeError("glfw.create_window() failed")
    glfw.make_context_current(window)
    glfw.swap_interval(1)
    # macOS core profile requires a non-zero VAO bound at all times.
    GL.glBindVertexArray(GL.glGenVertexArrays(1))
    Context.window = window
    Context.renderer = Renderer(WIDTH, HEIGHT)

    def _key_cb(
        win: Any, key: int, scancode: int, action: int, mods: int
    ) -> None:
        if action == glfw.PRESS:
            keyboard._press(key)
            if key == glfw.KEY_ESCAPE:  # Esc always quits (no title-bar needed)
                glfw.set_window_should_close(win, True)
        elif action == glfw.RELEASE:
            keyboard._release(key)

    glfw.set_key_callback(window, _key_cb)

    # Ctrl-C / SIGTERM (e.g. `podman stop`) ask the window to close between
    # frames; handlers are restored in the finally. Main-thread only.
    def _request_quit(_signum: int, _frame: Any) -> None:
        glfw.set_window_should_close(window, True)

    _prev_handlers: list[tuple[int, Any]] = []
    for _sig in (signal.SIGINT, signal.SIGTERM):
        try:
            _prev_handlers.append((_sig, signal.signal(_sig, _request_quit)))
        except (ValueError, OSError):
            pass

    # Fixed 60 Hz timestep -- beatstreets's update() takes no dt.
    _max_frames = int(os.environ.get("PGZERO_MAX_FRAMES", "0") or 0)
    _dt = 1.0 / 60.0
    _next_t = time.perf_counter()
    _frame_count = 0
    try:
        while not glfw.window_should_close(window):
            glfw.poll_events()
            update()
            fb_w, fb_h = glfw.get_framebuffer_size(window)
            Context.renderer.begin_frame(fb_width=fb_w, fb_height=fb_h)
            draw()
            glfw.swap_buffers(window)
            _frame_count += 1
            if _max_frames and _frame_count >= _max_frames:
                break
            _next_t += _dt
            _sleep = _next_t - time.perf_counter()
            if _sleep > 0:
                time.sleep(_sleep)
            else:
                _next_t = time.perf_counter()
    finally:
        for _sig, _prev in _prev_handlers:
            try:
                signal.signal(_sig, _prev)
            except (ValueError, OSError):
                pass
        # Stop the audio device's native callback thread before exit, else a
        # music-playing game hangs the process after the window closes.
        audio.shutdown()
        glfw.terminate()
